/**
 * ER-07-08: filter matrix, sensors and joint collision suppression (07 §5.9).
 *
 * The matrix scene places one cell per ordered layer pair (a, b) on a 3 m
 * grid: a dynamic sphere on layer a, a static box on layer b, overlapping.
 * The expected decision comes from the §5.9 rule, not from the adapter:
 * `(maskA & (1 << layerB)) !== 0 && (maskB & (1 << layerA)) !== 0`.
 * Values in `recorded` are generated by these tests, not invented.
 */
import { readFileSync } from "node:fs";
import { beforeAll, describe, expect, test } from "vitest";
import type {
  ColliderHandle,
  ContactEvent,
  TriggerEvent,
} from "../../src/index.js";
import {
  DT,
  bodyState,
  dynamicBox,
  dynamicSphere,
  init,
  makeWorld,
  staticBox,
  v3,
} from "../support/world.js";

interface FilterFixture {
  readonly world: {
    readonly gravity: readonly number[];
    readonly fixedDt: number;
  };
  readonly matrix: {
    readonly layerMasks: readonly number[];
    readonly spacing: number;
    readonly sphereRadius: number;
    readonly boxHalfExtents: readonly number[];
    readonly boxOffsetX: number;
  };
  readonly sensor: {
    readonly body: {
      readonly radius: number;
      readonly layer: number;
      readonly mask: number;
    };
    readonly sensor: {
      readonly halfExtents: readonly number[];
      readonly layer: number;
      readonly mask: number;
    };
    readonly ticks: number;
  };
  readonly joint: {
    readonly halfExtents: readonly number[];
    readonly positionA: readonly number[];
    readonly positionB: readonly number[];
    readonly anchorA: readonly number[];
    readonly anchorB: readonly number[];
    readonly ticks: number;
  };
  readonly recorded: {
    readonly observedInteractions: number | null;
    readonly observedRows: readonly number[] | null;
    readonly crossCellEvents: number | null;
    readonly sensorTriggerEnters: number | null;
    readonly sensorContactEvents: number | null;
    readonly sensorBodyDeltaM: number | null;
    readonly filteredSensorTriggerEnters: number | null;
    readonly jointCollideFalseContacts: number | null;
    readonly jointCollideTrueContacts: number | null;
    readonly unjointedContacts: number | null;
  };
}

const fixture = JSON.parse(
  readFileSync(
    new URL("../fixtures/filter-matrix.json", import.meta.url),
    "utf8",
  ),
) as FilterFixture;

const LAYER_COUNT = 32;

function popcount(value: number): number {
  let v = value >>> 0;
  let count = 0;
  while (v !== 0) {
    v &= v - 1;
    count += 1;
  }
  return count;
}

function isPair(
  event: ContactEvent,
  a: { readonly collider: ColliderHandle },
  b: { readonly collider: ColliderHandle },
): boolean {
  return (
    (event.colliderA === a.collider && event.colliderB === b.collider) ||
    (event.colliderA === b.collider && event.colliderB === a.collider)
  );
}

beforeAll(async () => {
  await init();
});

describe("filter-matrix fixture", () => {
  test(
    "[ER-07-08] all 1024 ordered layer pairs match the mutual-mask rule",
    () => {
      const w = fixture.world;
      const world = makeWorld({
        gravity: v3(w.gravity[0]!, w.gravity[1]!, w.gravity[2]!),
        fixedDt: w.fixedDt,
      });
      const matrix = fixture.matrix;
      const masks = matrix.layerMasks;
      expect(masks.length).toBe(LAYER_COUNT);

      const cellOf = new Map<ColliderHandle, number>();
      const expectedRows: number[] = new Array<number>(LAYER_COUNT).fill(0);
      for (let a = 0; a < LAYER_COUNT; a += 1) {
        for (let b = 0; b < LAYER_COUNT; b += 1) {
          const cell = a * LAYER_COUNT + b;
          const x = (a - (LAYER_COUNT - 1) / 2) * matrix.spacing;
          const z = (b - (LAYER_COUNT - 1) / 2) * matrix.spacing;
          const sphere = dynamicSphere(
            world,
            v3(x, 0, z),
            matrix.sphereRadius,
            {},
            { layer: a, mask: masks[a]! },
          );
          const box = staticBox(
            world,
            v3(x + matrix.boxOffsetX, 0, z),
            v3(
              matrix.boxHalfExtents[0]!,
              matrix.boxHalfExtents[1]!,
              matrix.boxHalfExtents[2]!,
            ),
            { layer: b, mask: masks[b]! },
          );
          cellOf.set(sphere.collider, cell);
          cellOf.set(box.collider, cell);
          /* 07 §5.9: both colliders must accept each other's layer. */
          const aAcceptsB = (masks[a]! & (1 << b)) !== 0;
          const bAcceptsA = (masks[b]! & (1 << a)) !== 0;
          if (aAcceptsB && bAcceptsA) {
            expectedRows[a] = (expectedRows[a]! | ((1 << b) >>> 0)) >>> 0;
          }
        }
      }
      expect(world.stats.bodyCount).toBe(LAYER_COUNT * LAYER_COUNT * 2);

      world.step(DT);
      const events: ContactEvent[] = [];
      const eventCount = world.drainContactEvents(events);

      const observedRows: number[] = new Array<number>(LAYER_COUNT).fill(0);
      let observedInteractions = 0;
      let crossCellEvents = 0;
      for (let i = 0; i < eventCount; i += 1) {
        const event = events[i]!;
        const cellA = cellOf.get(event.colliderA);
        const cellB = cellOf.get(event.colliderB);
        if (cellA === undefined || cellB === undefined || cellA !== cellB) {
          crossCellEvents += 1;
          continue;
        }
        const a = Math.floor(cellA / LAYER_COUNT);
        const b = cellA % LAYER_COUNT;
        if ((observedRows[a]! & (1 << b)) === 0) {
          observedRows[a] = (observedRows[a]! | ((1 << b) >>> 0)) >>> 0;
          observedInteractions += 1;
        }
      }

      let expectedInteractions = 0;
      for (let a = 0; a < LAYER_COUNT; a += 1) {
        expectedInteractions += popcount(expectedRows[a]!);
      }

      expect(crossCellEvents).toBe(0);
      expect(observedInteractions).toBe(expectedInteractions);
      for (let a = 0; a < LAYER_COUNT; a += 1) {
        expect(observedRows[a]).toBe(expectedRows[a]);
      }

      const recorded = fixture.recorded;
      if (recorded.observedInteractions !== null) {
        expect(observedInteractions).toBe(recorded.observedInteractions);
      }
      if (recorded.observedRows !== null) {
        expect(observedRows).toEqual(recorded.observedRows);
      }
      if (recorded.crossCellEvents !== null) {
        expect(crossCellEvents).toBe(recorded.crossCellEvents);
      }
      console.log(
        `[record filter-matrix] observedInteractions=${observedInteractions} crossCellEvents=${crossCellEvents} observedRows=${JSON.stringify(observedRows)}`,
      );
      world.dispose();
    },
    120_000,
  );

  test("[ER-07-08] sensors trigger, do not push, and obey filtering", () => {
    const w = fixture.world;
    const s = fixture.sensor;
    const world = makeWorld({
      gravity: v3(w.gravity[0]!, w.gravity[1]!, w.gravity[2]!),
      fixedDt: w.fixedDt,
    });
    const body = dynamicSphere(
      world,
      v3(0, 0, 0),
      s.body.radius,
      {},
      { layer: s.body.layer, mask: s.body.mask },
    );
    const sensor = staticBox(
      world,
      v3(0, 0, 0),
      v3(
        s.sensor.halfExtents[0]!,
        s.sensor.halfExtents[1]!,
        s.sensor.halfExtents[2]!,
      ),
      { sensor: true, layer: s.sensor.layer, mask: s.sensor.mask },
    );
    const before = bodyState();
    world.readBody(body.body, before);
    for (let tick = 0; tick < s.ticks; tick += 1) world.step(DT);
    const triggers: TriggerEvent[] = [];
    const triggerCount = world.drainTriggerEvents(triggers);
    const contacts: ContactEvent[] = [];
    const contactCount = world.drainContactEvents(contacts);
    const after = bodyState();
    world.readBody(body.body, after);
    const delta = Math.hypot(
      after.position.x - before.position.x,
      after.position.y - before.position.y,
      after.position.z - before.position.z,
    );

    expect(triggerCount).toBe(1);
    expect(triggers[0]!.phase).toBe("enter");
    expect(isPair(triggers[0]!, body, sensor)).toBe(true);
    expect(contactCount).toBe(0);
    expect(delta).toBeLessThan(1e-9);
    world.dispose();

    /* The same sensor pair with the body rejecting the sensor's layer. */
    const filteredWorld = makeWorld({
      gravity: v3(w.gravity[0]!, w.gravity[1]!, w.gravity[2]!),
      fixedDt: w.fixedDt,
    });
    dynamicSphere(
      filteredWorld,
      v3(0, 0, 0),
      s.body.radius,
      {},
      { layer: s.body.layer, mask: 0 },
    );
    staticBox(
      filteredWorld,
      v3(0, 0, 0),
      v3(
        s.sensor.halfExtents[0]!,
        s.sensor.halfExtents[1]!,
        s.sensor.halfExtents[2]!,
      ),
      { sensor: true, layer: s.sensor.layer, mask: s.sensor.mask },
    );
    for (let tick = 0; tick < s.ticks; tick += 1) filteredWorld.step(DT);
    const filteredTriggers: TriggerEvent[] = [];
    const filteredTriggerCount =
      filteredWorld.drainTriggerEvents(filteredTriggers);
    filteredWorld.dispose();

    expect(filteredTriggerCount).toBe(0);

    const recorded = fixture.recorded;
    if (recorded.sensorTriggerEnters !== null) {
      expect(triggerCount).toBe(recorded.sensorTriggerEnters);
    }
    if (recorded.sensorContactEvents !== null) {
      expect(contactCount).toBe(recorded.sensorContactEvents);
    }
    if (recorded.sensorBodyDeltaM !== null) {
      expect(delta).toBeCloseTo(recorded.sensorBodyDeltaM, 9);
    }
    if (recorded.filteredSensorTriggerEnters !== null) {
      expect(filteredTriggerCount).toBe(
        recorded.filteredSensorTriggerEnters,
      );
    }
    console.log(
      `[record filter-matrix] sensorTriggerEnters=${triggerCount} sensorContactEvents=${contactCount} sensorBodyDeltaM=${delta} filteredSensorTriggerEnters=${filteredTriggerCount}`,
    );
  });

  test("[ER-07-08] a joint suppresses its pair's contacts only when collideConnected is false", () => {
    const w = fixture.world;
    const j = fixture.joint;
    const half = v3(
      j.halfExtents[0]!,
      j.halfExtents[1]!,
      j.halfExtents[2]!,
    );
    const pairContacts = (collideConnected: boolean | null): number => {
      const world = makeWorld({
        gravity: v3(w.gravity[0]!, w.gravity[1]!, w.gravity[2]!),
        fixedDt: w.fixedDt,
      });
      const a = dynamicBox(
        world,
        v3(j.positionA[0]!, j.positionA[1]!, j.positionA[2]!),
        half,
      );
      const b = dynamicBox(
        world,
        v3(j.positionB[0]!, j.positionB[1]!, j.positionB[2]!),
        half,
      );
      if (collideConnected !== null) {
        world.createJoint({
          kind: "fixed",
          bodyA: a.body,
          bodyB: b.body,
          anchorA: v3(j.anchorA[0]!, j.anchorA[1]!, j.anchorA[2]!),
          anchorB: v3(j.anchorB[0]!, j.anchorB[1]!, j.anchorB[2]!),
          collideConnected,
        });
      }
      for (let tick = 0; tick < j.ticks; tick += 1) world.step(DT);
      const events: ContactEvent[] = [];
      const count = world.drainContactEvents(events);
      let pair = 0;
      for (let i = 0; i < count; i += 1) {
        if (isPair(events[i]!, a, b)) pair += 1;
      }
      world.dispose();
      return pair;
    };

    const collideFalse = pairContacts(false);
    const collideTrue = pairContacts(true);
    const unjointed = pairContacts(null);

    expect(collideFalse).toBe(0);
    expect(collideTrue).toBe(1);
    expect(unjointed).toBe(1);

    const recorded = fixture.recorded;
    if (recorded.jointCollideFalseContacts !== null) {
      expect(collideFalse).toBe(recorded.jointCollideFalseContacts);
    }
    if (recorded.jointCollideTrueContacts !== null) {
      expect(collideTrue).toBe(recorded.jointCollideTrueContacts);
    }
    if (recorded.unjointedContacts !== null) {
      expect(unjointed).toBe(recorded.unjointedContacts);
    }
    console.log(
      `[record filter-matrix] jointCollideFalseContacts=${collideFalse} jointCollideTrueContacts=${collideTrue} unjointedContacts=${unjointed}`,
    );
  });
});
